widget.solution:
def sse(values):
    """Squared error around the mean; 0.0 for an empty list."""
    if not values:
        return 0.0
    m = sum(values) / len(values)
    return sum((v - m) ** 2 for v in values)

def sse_gain(y_left, y_right):
    parent = list(y_left) + list(y_right)
    return round(sse(parent) - sse(list(y_left)) - sse(list(y_right)), 6)
